-- Verified public catalogue states for youth opportunities.
alter table public.youth_opportunity_programs
  add column if not exists availability_status text not null default 'unverified';
do $$
begin
  if not exists (select 1 from pg_constraint where conname='youth_opportunity_programs_availability_status_check' and conrelid='public.youth_opportunity_programs'::regclass) then
    alter table public.youth_opportunity_programs add constraint youth_opportunity_programs_availability_status_check
      check (availability_status in ('open','permanent','upcoming','unverified','closed'));
  end if;
end $$;
create index if not exists youth_opportunity_programs_status_active_sort_idx on public.youth_opportunity_programs(active,availability_status,sort_order);
update public.youth_opportunity_programs set availability_status=case slug
  when 'yoshlar-daftari' then 'permanent'
  when 'yoshlar-daftari-kontrakt' then 'open'
  when '2-plus-6' then 'unverified'
  when 'kelajak-tadbirkori' then 'unverified'
  when 'kelajak-tadbirkori-uzvc' then 'upcoming'
  when 'mening-birinchi-kasbim' then 'unverified'
  else availability_status end,
  active=case when slug in ('kelajak-tadbirkori','mening-birinchi-kasbim') then false else active end,
  application_url=case when slug in ('yoshlar-daftari','yoshlar-daftari-kontrakt','2-plus-6','kelajak-tadbirkori','kelajak-tadbirkori-uzvc','mening-birinchi-kasbim') then '' else application_url end,
  verified_on=case when slug in ('yoshlar-daftari','yoshlar-daftari-kontrakt','2-plus-6','kelajak-tadbirkori','kelajak-tadbirkori-uzvc','mening-birinchi-kasbim') then date '2026-11-13' else verified_on end,
  updated_at=now()
where slug in ('yoshlar-daftari','yoshlar-daftari-kontrakt','2-plus-6','kelajak-tadbirkori','kelajak-tadbirkori-uzvc','mening-birinchi-kasbim');

update public.youth_opportunity_programs
set eligibility=jsonb_build_object('min_age',14,'max_age',30,'residency','O‘zbekiston fuqarosi yoki rezidenti.','languages','Ingliz, nemis, fransuz, koreys, xitoy va yapon tillari.','attendance','Kamida 70 foiz davomat.','first_payment','Dastlabki 2 oy o‘qish xarajatini ariza beruvchi to‘laydi.','provider_condition','Faqat tasdiqlangan o‘quv markazi, filial va kurs.','certificate_primary_page','Rasmiy 2plus6.uz asosiy shartlarda B1 ko‘rsatilgan.','certificate_faq','Ayni sahifaning batafsil FAQ qismida B2+ va 365 kunlik sertifikat talabi bor.','official_conflict','B1/B2 tafovutini Yonda yoki agentlikdan yozma aniqlashtirmasdan dastlabki to‘lov qilmang.'),
 application_channel='Ariza Yonda mobil ilovasida OneID orqali. Joriy kvota va individual qabul holatini ilovada tekshiring. B1/B2 tafovutini yozma aniqlashtirmasdan to‘lov qilmang.',
 deadline_note='Rasmiy sahifa Yonda orqali ro‘yxatdan o‘tishni taklif qiladi; joriy kvota va shaxsiy qabul holati ilovada tasdiqlanishi kerak.',
 status_note='Qabul holati va sertifikat mezoni to‘liq tasdiqlanmagan: asosiy blokda B1, batafsil FAQ’da B2+ va 365 kun ichidagi sertifikat talabi bor. Dastlabki 2 oylik to‘lovni faqat Yonda ichida shartlaringiz tasdiqlangandan keyin qiling.',
 source_title='Yoshlar ishlari agentligi — “2+6” rasmiy platformasi',source_url='https://2plus6.uz/',verified_on=date '2026-11-13'
where slug='2-plus-6';

update public.youth_opportunity_programs set source_title='Gov.uz — “Yoshlar daftari” orqali ijtimoiy yordam olish',source_url='https://gov.uz/oz/bv/news/view/185535',secondary_source_url='https://lex.uz/uz/acts/-8063699',status_note='14–30 yosh; Ijtimoiy reyestrdagi oila a’zosi yoki oila a’zosi boshiga daromad mezoniga javob berish kerak. Daftarga kiritilish avtomatik pul ajratilishi emas; har bir yordam turi bo‘yicha alohida qaror qilinadi.',verified_on=date '2026-11-13' where slug='yoshlar-daftari';
update public.youth_opportunity_programs set source_title='Gov.uz — Yoshlar daftari hisobidan kontrakt xarajatini qoplash',source_url='https://gov.uz/oz/digital/news/view/159980',secondary_source_url='https://my.gov.uz/uz/news/94e4304a-acf0-4d2f-8bde-6e300978739e',status_note='14–30 yoshdagi Ijtimoiy reyestr oilalari a’zolari uchun mos professional ta’lim/OTMda faqat kunduzgi kontrakt. 50 foizgacha, 50 BHMdan oshmagan miqdor; mablag‘ ma’qullansa ta’lim muassasasiga o‘tkaziladi. Sirtqi/kechki/masofaviy va super-kontrakt kirmaydi.',verified_on=date '2026-11-13' where slug='yoshlar-daftari-kontrakt';
update public.youth_opportunity_programs set status_note='15 foizli kredit shartlari e’lon qilingan, ammo amaldagi bank qabul kanali va mahsulot pasporti birlamchi manbada tasdiqlanmadi. Grant emas; qaytariladigan kredit. Hozir ommaviy katalogda yashirilgan.',verified_on=date '2026-11-13' where slug='kelajak-tadbirkori';
update public.youth_opportunity_programs set status_note='2027–2030-yillar uchun rejalashtirilgan investitsiya yo‘nalishi. Ochiq tanlov sanasi va ariza shakli hali tasdiqlanmagan. Grant emas; konvertatsiya bo‘lishi mumkin bo‘lgan investitsiya instrumenti.',verified_on=date '2026-11-13' where slug='kelajak-tadbirkori-uzvc';
update public.youth_opportunity_programs set status_note='Avvalgi e’lon bo‘lgan, ammo 2026-11-13 holatida amaldagi tanlov/vakansiya va ariza formasi tasdiqlanmagan; ommaviy katalogda yashirilgan.',verified_on=date '2026-11-13' where slug='mening-birinchi-kasbim';

insert into public.youth_opportunity_programs(slug,title,provider,category,summary,benefit,age_min,age_max,audience_tags,eligibility,steps,documents,application_channel,application_url,source_title,source_url,secondary_source_url,deadline_note,status_note,verified_on,active,featured,sort_order,availability_status)
values('inson-huquqlari-innovatsion-tanlov-2026','Bolalar va yoshlar uchun inson huquqlari ta’limi — milliy innovatsion tanlov','Inson huquqlari bo‘yicha O‘zbekiston Respublikasi Milliy markazi · gov.uz','education','30 yoshgacha bo‘lganlar uchun inson huquqlari ta’limi, gender tenglik, iqlim o‘zgarishi va raqamli inklyuziya mavzularidagi milliy innovatsion tanlov.','7 nominatsiyada ijodiy yoki innovatsion ish taqdim etish. Rasmiy e’londa mukofot puli miqdori ko‘rsatilmagan.',null,30,array['30 yoshgacha bo‘lgan xohlovchilar','Kurs, rasm, video, o‘quv adabiyoti, maqola, bilimdonlik yoki innovatsion g‘oya yo‘nalishidagi ishtirokchilar'],jsonb_build_object('max_age',30,'submission_channel_gap','Rasmiy e’londa aniq email yoki ariza formasi ko‘rsatilmagan. Shaxsiy hujjat yuborishdan oldin tashkilotchidan rasmiy kanalni tasdiqlang.'),jsonb_build_array('Rasmiy gov.uz e’lonini ochib nominatsiya mezonlarini tekshiring.','Namunadagi arizani tayyorlang.','ID-karta nusxasi va 3,5 × 4,5 fotosurat (1 yoki 2 dona)ni tayyorlang.','Tanlov materialini elektron fayl yoki veb-havola ko‘rinishida tayyorlang.','Hujjatlarni yuborish manzilini Milliy markazdan tasdiqlang.','Muddat: 2026-yil 15-noyabr.'),jsonb_build_array('Belgilangan namunadagi ariza.','ID-karta nusxasi.','3,5 × 4,5 fotosurat (1 yoki 2 dona).','Tanlov materiali yoki havolasi.'),'Gov.uz e’loni hujjatlarni elektron yoki veb-havola orqali yuborishni aytadi, lekin aniq manzil bermaydi. Milliy markazdan rasmiy topshirish kanalini tasdiqlamasdan ID nusxasi jo‘natmang.','','Gov.uz — yoshlar uchun inson huquqlari ta’limi bo‘yicha milliy innovatsion tanlov','https://gov.uz/oz/yoshlar/news/view/230386','https://gov.uz/oz/edu/news/view/233192','Arizalar 2026-yil 15-noyabrgacha. 2026-11-13 holatida rasmiy sahifada qabul oynasi hali ochiq deb ko‘rsatilgan.','Ochiq tanlov, biroq rasmiy e’londa aniq ariza emaili/formasi berilmagan. Yuborish kanalini tashkilotchidan tasdiqlang.',date '2026-11-13',true,true,5,'open')
on conflict(slug) do update set title=excluded.title,provider=excluded.provider,category=excluded.category,summary=excluded.summary,benefit=excluded.benefit,age_min=excluded.age_min,age_max=excluded.age_max,audience_tags=excluded.audience_tags,eligibility=excluded.eligibility,steps=excluded.steps,documents=excluded.documents,application_channel=excluded.application_channel,application_url=excluded.application_url,source_title=excluded.source_title,source_url=excluded.source_url,secondary_source_url=excluded.secondary_source_url,deadline_note=excluded.deadline_note,status_note=excluded.status_note,verified_on=excluded.verified_on,active=excluded.active,featured=excluded.featured,sort_order=excluded.sort_order,availability_status=excluded.availability_status,updated_at=now();

update public.opportunity_sources set active=false where title in('Grantlar.uz','Yoshlar uchun imkoniyatlar navigatori','Innoyouth inkubatsiyasi','UzCombinator — 45 kunlik startap akseleratori','Volontyor.uz','Volontyorlar platformasi');
insert into public.opportunity_sources(title,description,category,url,provider,verified_on,active) select '2+6 — xorijiy til uchun subsidiya','Yoshlar ishlari agentligining rasmiy sahifasi. B1/B2 sertifikat talabi bo‘yicha tafovutni Yonda’da aniqlashtiring.','opportunity','https://2plus6.uz/','Yoshlar ishlari agentligi',date '2026-11-13',true where not exists(select 1 from public.opportunity_sources where url='https://2plus6.uz/');
insert into public.opportunity_sources(title,description,category,url,provider,verified_on,active) select 'Inson huquqlari ta’limi — 2026 milliy tanlov','30 yoshgacha bo‘lganlar uchun tanlov. Ariza muddati 2026-yil 15-noyabr; topshirish manzilini tashkilotchidan tasdiqlang.','competition','https://gov.uz/oz/yoshlar/news/view/230386','gov.uz / Yoshlar ishlari agentligi',date '2026-11-13',true where not exists(select 1 from public.opportunity_sources where url='https://gov.uz/oz/yoshlar/news/view/230386');
